function PromqlForgePure(){
  var AGGS=['sum','avg','count','min','max','stddev','stdvar','group','count_values','quantile','topk','bottomk'];
  function isAgg(f){ return AGGS.indexOf(f)>=0; }
  // ---------- 词法分析 ----------
  function tokenize(q){
    var toks=[], i=0, n=q.length;
    function isId(c){ return /[a-zA-Z0-9_:.\x80-\uffff]/.test(c); }
    while(i<n){
      var c=q[i];
      if(/\s/.test(c)){ i++; continue; }
      if(c==='"'||c==="'"){
        var quote=c, j=i+1, str='';
        while(j<n && q[j]!==quote){ if(q[j]==='\\'&&j+1<n) j++; str+=q[j]; j++; }
        toks.push({type:'string', value:str}); i=j+1; continue;
      }
      if(/[0-9]/.test(c) || (c==='.'&&/[0-9]/.test(q[i+1]||''))){
        var k=i; while(k<n && /[0-9.eE+\-]/.test(q[k])) k++;
        // 简易：数后若紧跟单位（s m h d w y）也吞掉
        while(k<n && /[smhdwy]/.test(q[k])) k++;
        toks.push({type:'number', value:q.slice(i,k)}); i=k; continue;
      }
      if(/[a-zA-Z_]/.test(c)){
        var k=i; while(k<n && isId(q[k])) k++;
        var w=q.slice(i,k); toks.push({type:isAgg(w)?'agg':'ident', value:w}); i=k; continue;
      }
      // 运算符 / 标点
      var two=q.substr(i,2);
      if(['==','!=','=~','!~','>=','<=','->'].indexOf(two)>=0){ toks.push({type:'op', value:two}); i+=2; continue; }
      toks.push({type:'punct', value:c}); i++;
    }
    return toks;
  }
  // ---------- 解释 ----------
  function splitMatchers(s){
    return s.split(',').map(function(x){return x.trim();}).filter(Boolean);
  }
  function explain(q){
    q=(q||'').trim();
    if(!q) return {error:'请输入 PromQL 查询'};
    var notes=[];
    // 指标名（未被 ( 紧跟的标识符）
    var metricMatch=q.match(/\b([a-zA-Z_:][a-zA-Z0-9_:]*)\b(?!\s*\()/);
    var metric=metricMatch?metricMatch[1]:null;
    // 标签匹配器 metric{...}
    var matcherRe=/([a-zA-Z_:][a-zA-Z0-9_:]*)\s*\{([^}]*)\}/g, mm, matchers=[];
    while((mm=matcherRe.exec(q))){ matchers.push({metric:mm[1], conds:splitMatchers(mm[2])}); }
    // 范围向量 [...]
    var rangeRe=/\[([^\]]+)\]/g, ranges=[]; while((mm=rangeRe.exec(q))) ranges.push(mm[1]);
    // offset
    var offRe=/offset\s+([0-9a-z]+)/g, offsets=[]; while((mm=offRe.exec(q))) offsets.push(mm[1]);
    // 聚合（支持 sum(...) by (...) 与独立聚合）
    var aggFnRe=/\b(sum|avg|count|min|max|stddev|stdvar|group|quantile|topk|bottomk|count_values)\b(?=\s*\()/g;
    var aggFns=[], am; while((am=aggFnRe.exec(q))){ aggFns.push({fn:am[1], pos:am.index}); }
    var byRe=/\b(by|without)\s*\(([^)]*)\)/g, consumed={};
    while((mm=byRe.exec(q))){
      var kind=mm[1], labels=mm[2], pos=mm.index, fn=null;
      for(var k=0;k<aggFns.length;k++){ if(aggFns[k].pos<pos){ fn=aggFns[k].fn; consumed[aggFns[k].pos]=true; } }
      notes.push('聚合：'+(fn||'聚合')+(kind==='without'?(' without ('+labels+')'):(' by ('+labels+')')));
    }
    aggFns.forEach(function(a){ if(!consumed[a.pos]) notes.push('聚合：'+a.fn); });
    // 函数调用
    var fnRe=/\b([a-zA-Z_][a-zA-Z0-9_]*)\s*\(/g, fns=[]; while((mm=fnRe.exec(q))){ fns.push(mm[1]); }
    if(metric) notes.push('指标：'+metric);
    matchers.forEach(function(m){ notes.push('标签过滤：'+m.metric+'{'+m.conds.join(', ')+'}'); });
    ranges.forEach(function(r){ notes.push('范围向量：['+r+']'); });
    offsets.forEach(function(o){ notes.push('偏移：offset '+o); });
    fns.forEach(function(f){ if(!isAgg(f)) notes.push('函数：'+f+'()'); });
    return {error:null, notes:notes, metric:metric, range:ranges[0]||null, tokens:tokenize(q)};
  }
  // ---------- 构建 ----------
  function build(spec){
    spec=spec||{};
    var sel=spec.metric||'';
    if(spec.filters && spec.filters.length){
      var conds=spec.filters.filter(function(f){return f.k&&f.v;}).map(function(f){return f.k+(f.op||'=')+'"'+f.v+'"';});
      if(conds.length) sel+='{'+conds.join(', ')+'}';
    }
    if(spec.range) sel=sel+'['+spec.range+']';
    if(spec.fn) sel=spec.fn+'('+sel+')';
    if(spec.agg){
      sel=spec.agg+'('+sel+')'+(spec.aggLabels?(' by ('+spec.aggLabels+')'):'');
    }
    if(spec.offset) sel+=' offset '+spec.offset;
    return {error:null, query:sel.trim()};
  }
  var api={tokenize:tokenize, explain:explain, build:build, isAgg:isAgg};
  if(typeof window!=='undefined'){ window.__PURE__=api; }
  if(typeof module!=='undefined'&&module.exports){ module.exports={PromqlForgePure:PromqlForgePure}; }
  return api;
}
